create table if not exists admins(id bigint generated by default as identity primary key,username text unique not null,password_hash text not null);
create table if not exists categories(id bigint generated by default as identity primary key,name text unique not null);
create table if not exists orders(id bigint generated by default as identity primary key,title text not null,order_no text,order_date date,category_id bigint not null references categories(id),description text,storage_path text not null,original_name text not null,created_at timestamptz default now());
alter table admins enable row level security; alter table categories enable row level security; alter table orders enable row level security;